package com.qrid.servlet;
import com.qrid.dao.*;import com.qrid.model.User;import com.qrid.util.*;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.IOException;import java.util.Set;
@WebServlet("/admin/users") public class UserManagementServlet extends HttpServlet{
 protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{String id=r.getParameter("edit");if(id!=null)r.setAttribute("editUser",new UserDao().find(Long.parseLong(id)));r.setAttribute("users",new UserDao().list(r.getParameter("q")));r.getRequestDispatcher("/WEB-INF/views/admin/users.jsp").forward(r,s);}catch(Exception e){throw new ServletException(e);}}
 protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException,ServletException{User actor=(User)r.getSession().getAttribute("user");try{UserDao d=new UserDao();String action=r.getParameter("action");if("toggle".equals(action)){d.toggle(Long.parseLong(r.getParameter("id")),actor.getId());Flash.set(r,"success","Account status changed.");}else{long id=r.getParameter("id").isBlank()?0:Long.parseLong(r.getParameter("id"));String name=Validation.text(r.getParameter("name"),100),email=Validation.text(r.getParameter("email"),120),role=r.getParameter("role"),dept=Validation.text(r.getParameter("department"),100),status=r.getParameter("status"),password=r.getParameter("password");if(name.length()<2||!Validation.email(email)||!Set.of("ADMIN","SECURITY","STAFF").contains(role))throw new IllegalArgumentException("Enter valid user details.");if(id==0&&(password==null||password.length()<8))throw new IllegalArgumentException("New accounts require a password of at least 8 characters.");d.save(id,name,email,password==null||password.isBlank()?null:PasswordUtil.hash(password),role,dept,status);Flash.set(r,"success","User account saved.");}new AuditDao().log(actor.getId(),"USER_MANAGEMENT","USER",r.getParameter("id"),action,r.getRemoteAddr());}catch(Exception e){Flash.set(r,"danger",e.getMessage());}s.sendRedirect(r.getContextPath()+"/admin/users");}
}
